@CrossOrigin
@RestController
@RequestMapping("/PurchaseOrderQuery")
public class PurchaseOrderQueryRestController extends BaseSpringRestController {
	
	public PurchaseOrderQueryRestController( PurchaseOrderService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a PurchaseOrder using a UUID
     * @param		UUID purchaseOrderId
     * @return		PurchaseOrder
     */    
    @GetMapping("/load")
    public PurchaseOrder load( @RequestParam(required=true) UUID purchaseOrderId ) {
    	PurchaseOrder entity = null;

    	try {  
    		entity = service.getPurchaseOrder( new PurchaseOrderFetchOneSummary( purchaseOrderId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load PurchaseOrder using Id " + purchaseOrderId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all PurchaseOrder business objects
     * @return		Set<PurchaseOrder>
     */
    @GetMapping("/")
    public List<PurchaseOrder> loadAll() {                
    	List<PurchaseOrder> purchaseOrderList = null;
        
    	try {
            // load the PurchaseOrder
            purchaseOrderList = service.getAllPurchaseOrder();
            
            if ( purchaseOrderList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all PurchaseOrders" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all PurchaseOrders ", exc );
        	return null;
        }

        return purchaseOrderList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected PurchaseOrder purchaseOrder = null;
    protected PurchaseOrderService service = null;
    private static final Logger LOGGER = Logger.getLogger(PurchaseOrderQueryRestController.class.getName());
    
}
